import java.util.*;

public class Main {
    static long rankOf(long[] p, int i, boolean[] used, long[] fact) {
        int n = p.length;
        if (i == n) return 0;
        long smaller = 0;
        for (int v = 1; v < p[i]; v++) {
            if (!used[v]) smaller++;
        }
        used[(int) p[i]] = true;
        return smaller * fact[n - 1 - i] + rankOf(p, i + 1, used, fact);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long[] p = new long[(int) n];
        for (int i = 0; i < p.length; i++) p[i] = sc.nextLong();

        long[] fact = new long[(int) n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i;
        System.out.println(rankOf(p, 0, new boolean[(int) n + 1], fact) + 1);
    }
}
